import '../../domain/entities/order.dart';import '../../domain/repositories/order_repository.dart';import '../datasources/order_remote_datasource.dart';class OrderRepositoryImpl implements OrderRepository{final OrderRemoteDataSource remote;OrderRepositoryImpl({required this.remote});@override Future<List<OrderEntity>> getOrders()=>remote.getOrders();@override Future<OrderEntity> createOrder({String? tableId,String? waitressId,required List<OrderItem> items})=>remote.createOrder(tableId:tableId,waitressId:waitressId,items:items);@override Future<OrderEntity> updateOrderStatus({required String orderId,required String status})async=>throw UnimplementedError('Ajouter PATCH /orders/:id/status selon le contrat API.');}
